-- --------------------------------------------------------
-- 4. UserLinks & ReferenceUserLinks (매핑 로직)
-- --------------------------------------------------------
-- User 502에게 모든 링크 연결 (105개)
SELECT 502, link_id, 'UNREAD', 0, '관심 자료', '자동 분류 테스트 데이터', NOW(), NOW()
FROM links;

-- URL 키워드를 기반으로 Reference ID(폴더) 자동 배정
SELECT
    CASE
        -- [511 경제]
        WHEN l.url LIKE '%news%' OR l.url LIKE '%hankyung%' OR l.url LIKE '%mk.co.kr%' OR l.url LIKE '%finance%' OR l.url LIKE '%biz%' OR l.url LIKE '%bloomberg%' OR l.url LIKE '%wsj%' OR l.url LIKE '%economist%' THEN 511

        -- [512 뷰티]
        WHEN l.url LIKE '%vogue%' OR l.url LIKE '%elle%' OR l.url LIKE '%musinsa%' OR l.url LIKE '%allure%' OR l.url LIKE '%glowpick%' OR l.url LIKE '%marieclaire%' OR l.url LIKE '%gq%' OR l.url LIKE '%bazaar%' OR l.url LIKE '%cosmo%' THEN 512

        -- [513 요리]
        WHEN l.url LIKE '%recipe%' OR l.url LIKE '%cooking%' OR l.url LIKE '%kurly%' OR l.url LIKE '%baking%' OR l.url LIKE '%foodie%' OR l.url LIKE '%pasta%' OR l.url LIKE '%dietfood%' OR l.url LIKE '%bluebottle%' OR l.url LIKE '%steak%' THEN 513

        -- [514 건강]
        WHEN l.url LIKE '%health%' OR l.url LIKE '%physical%' OR l.url LIKE '%nike%' OR l.url LIKE '%webmd%' OR l.url LIKE '%yoga%' OR l.url LIKE '%medipana%' OR l.url LIKE '%abs%' OR l.url LIKE '%mindful%' OR l.url LIKE '%stretching%' OR l.url LIKE '%backpain%' THEN 514

        -- [515 인문]
        WHEN l.url LIKE '%wiki%' OR l.url LIKE '%psychology%' OR l.url LIKE '%ted%' OR l.url LIKE '%terms.naver%' OR l.url LIKE '%history%' OR l.url LIKE '%art-insight%' OR l.url LIKE '%philosophy%' OR l.url LIKE '%bookclub%' OR l.url LIKE '%art%' THEN 515

        -- [516 커리어]
        WHEN l.url LIKE '%linkedin%' OR l.url LIKE '%wanted%' OR l.url LIKE '%velog%' OR l.url LIKE '%programmers%' OR l.url LIKE '%eo%' OR l.url LIKE '%work%' OR l.url LIKE '%learning%' OR l.url LIKE '%tech%' OR l.url LIKE '%salary%' OR l.url LIKE '%job%' OR l.url LIKE '%startup%' OR l.url LIKE '%leadership%' OR l.url LIKE '%frontend%' OR l.url LIKE '%insight%' THEN 516

        -- [517 리빙]
        WHEN l.url LIKE '%ohou%' OR l.url LIKE '%ikea%' OR l.url LIKE '%pinterest%' OR l.url LIKE '%living%' OR l.url LIKE '%diy%' OR l.url LIKE '%interior%' OR l.url LIKE '%color%' OR l.url LIKE '%clean%' OR l.url LIKE '%storage%' THEN 517

        -- 나머지는 미지정(510)
        ELSE 510
        END,
    ul.user_link_id,
    NOW(),
    NOW()
FROM user_links ul
         JOIN links l ON ul.link_id = l.link_id
WHERE ul.user_id = 502;

-- --------------------------------------------------------
-- 5. 검증
-- --------------------------------------------------------
SELECT r.title, COUNT(rul.reference_user_link_id) as count
FROM reference r
    LEFT JOIN reference_user_links rul ON r.reference_id = rul.reference_id
WHERE r.user_id = 502
GROUP BY r.reference_id;