INSERT INTO links (url, title, ai_summary, content, created_at, updated_at) VALUES
                                                                                ('https://n.news.naver.com/mnews/article/001/1', '뉴욕증시, 금리 인하 기대감에 상승 마감', '미국 연준의 통화 정책 완화 시그널에 힘입어 뉴욕 3대 지수가 나란히 사상 최고치를 경신했습니다. 특히 기술주 중심의 매수세가 유입되며 나스닥 지수의 상승폭이 두드러졌습니다. 시장 전문가들은 인플레이션 지표가 안정화됨에 따라 연내 금리 인하가 확실시된다고 분석하고 있습니다. 다만, 고용 시장이 여전히 과열 양상을 보이고 있어 급격한 인하는 어려울 것이라는 신중론도 제기됩니다.', 'Economy', NOW(), NOW()),
                                                                                ('https://www.hankyung.com/economy/article/1', '한국 반도체 수출 6개월 연속 흑자', '메모리 반도체 가격의 회복과 AI 서버 수요의 폭발적인 증가로 인해 국내 반도체 기업들의 실적이 뚜렷한 개선세를 보이고 있습니다. 삼성전자와 SK하이닉스는 고대역폭 메모리(HBM) 시장에서의 우위를 바탕으로 6개월 연속 수출 흑자를 기록했습니다. 이러한 흐름은 하반기까지 지속될 것으로 보이며, 한국 경제 성장률 반등의 핵심 동력이 될 전망입니다. 정부 또한 반도체 클러스터 조성을 위한 지원을 아끼지 않겠다고 발표했습니다.', 'Economy', NOW(), NOW()),
                                                                                ('https://www.mk.co.kr/news/economy/1', '부동산 시장, 서울과 지방 양극화 심화', '서울 강남 3구와 주요 마용성 지역은 신고가를 경신하며 뜨거운 열기를 보이고 있지만, 지방은 미분양 물량이 적체되며 침체의 늪에서 벗어나지 못하고 있습니다. 고금리 기조가 유지되면서 대출 이자 부담을 느낀 실수요자들이 똘똘한 한 채로 몰리는 현상이 가속화되고 있습니다. 전문가들은 이러한 양극화 현상이 당분간 지속될 것이며, 지방 부동산 시장 활성화를 위한 특단의 대책이 필요하다고 입을 모읍니다.', 'Economy', NOW(), NOW()),
                                                                                ('https://finance.naver.com/marketindex/1', '원달러 환율 1300원대 등락 지속', '미국의 경제 지표 호조로 인해 달러 강세 기조가 유지되면서 원달러 환율이 1300원대 중반에서 등락을 거듭하고 있습니다. 한국은행은 환율 변동성 확대에 따른 외환 시장 개입 가능성을 시사하며 시장 안정을 도모하고 있습니다. 수출 기업들은 환율 상승으로 인한 가격 경쟁력 확보에 안도하는 반면, 수입 물가 상승을 우려하는 목소리도 높습니다. 향후 연준의 금리 결정이 환율의 향방을 가를 중요한 변수가 될 것입니다.', 'Economy', NOW(), NOW()),
                                                                                ('https://biz.chosun.com/stock/1', '비트코인 ETF 승인 이후 자금 유입 가속', '미국 증권거래위원회(SEC)의 현물 ETF 승인 이후, 비트코인 시장에 기관 투자자들의 자금이 대거 유입되고 있습니다. 이는 가상자산이 제도권 금융 상품으로 인정받았다는 것을 의미하며, 디지털 금으로서의 가치가 재평가되고 있음을 시사합니다. 비트코인 가격은 연일 상승세를 기록하며 전고점 돌파를 눈앞에 두고 있습니다. 하지만 변동성이 여전히 큰 만큼 투자자들의 신중한 접근이 요구됩니다.', 'Economy', NOW(), NOW()),
                                                                                ('https://www.bloomberg.com/asia', 'Asian Markets Mixed as Investors Weigh China Data', '중국의 경기 부양책 발표에도 불구하고 실물 경제 지표가 예상보다 부진하게 나오면서 아시아 증시가 혼조세를 보이고 있습니다. 일본 증시는 엔저 효과에 힘입어 상승세를 이어가고 있는 반면, 홍콩과 상해 증시는 하락 압력을 받고 있습니다. 투자자들은 중국 정부의 추가적인 부양책 여부와 부동산 시장의 회복 속도를 주시하고 있습니다. 글로벌 공급망 재편 움직임 또한 아시아 시장에 불확실성을 더하는 요인입니다.', 'Economy', NOW(), NOW()),
                                                                                ('https://www.wsj.com/economy/1', 'Fed signals rate cuts coming in 2024', '연방준비제도(Fed)가 최근 회의록을 통해 2024년 내 금리 인하 가능성을 강력하게 시사했습니다. 물가 상승률이 목표치인 2%에 근접하고 있다는 데이터가 연준의 정책 전환을 뒷받침하고 있습니다. 시장 참여자들은 첫 번째 금리 인하 시점이 6월이 될 것으로 예측하며 자산 배분 전략을 수정하고 있습니다. 다만, 연준 의장은 데이터에 기반한 신중한 결정을 내릴 것임을 거듭 강조했습니다.', 'Economy', NOW(), NOW()),
                                                                                ('https://n.news.naver.com/mnews/article/001/2', '국내 스타트업 투자 혹한기, 언제 풀리나', '고금리와 경기 침체 우려로 인해 벤처 캐피탈(VC)의 투자 심리가 위축되면서 국내 스타트업들이 자금 조달에 어려움을 겪고 있습니다. 옥석 가리기가 본격화되면서 수익 모델이 확실한 기업만이 투자를 유치하는 빈익빈 부익부 현상이 심화되고 있습니다. 정부는 모태펀드 예산을 증액하고 세제 혜택을 강화하는 등 스타트업 생태계 지원에 나섰습니다. 업계에서는 내년 상반기부터는 투자 환경이 점차 개선될 것으로 기대하고 있습니다.', 'Economy', NOW(), NOW()),
                                                                                ('https://www.hankyung.com/realestate/1', '전세사기 여파, 빌라 기피 현상 심화', '전세사기 사건의 여파로 인해 빌라와 오피스텔 등 비아파트 주거 시장에 대한 불신이 커지고 있습니다. 세입자들은 보증금을 떼일까 우려하여 월세를 선호하거나 무리해서라도 아파트 전세로 이동하려는 경향을 보입니다. 이로 인해 빌라 전세 가격은 하락하고 아파트 전세 가격은 상승하는 현상이 나타나고 있습니다. 주거 사다리가 붕괴될 수 있다는 우려 속에 정부의 근본적인 대책 마련이 시급합니다.', 'Economy', NOW(), NOW()),
                                                                                ('https://finance.yahoo.com/news/tech', 'AI Boom Drives Tech Stocks Higher', '생성형 AI 기술의 혁신이 전 산업으로 확산되면서 엔비디아, 마이크로소프트 등 관련 기술주들의 주가가 폭등하고 있습니다. AI 데이터센터 구축을 위한 반도체 수요가 급증하고 있으며, 이는 하드웨어 및 소프트웨어 기업 전반에 호재로 작용하고 있습니다. 월가 분석가들은 AI가 인터넷의 탄생에 비견될 만한 생산성 혁명을 가져올 것이라고 평가합니다. 그러나 단기 과열에 따른 버블 붕괴를 경계해야 한다는 목소리도 존재합니다.', 'Economy', NOW(), NOW()),
                                                                                ('https://n.news.naver.com/mnews/article/001/3', '고물가에 점심값 부담, 런치플레이션', '외식 물가가 가파르게 상승하면서 직장인들의 점심 식대 부담이 커지는 런치플레이션(Lunchflation) 현상이 지속되고 있습니다. 만 원으로 한 끼를 해결하기 어려워지자 편의점 도시락이나 구내식당을 이용하는 알뜰족이 늘어나고 있습니다. 식품 기업들은 가성비를 앞세운 간편식 제품 라인업을 확대하며 이러한 수요에 대응하고 있습니다. 고물가 상황이 장기화될 것으로 보여 서민들의 지갑 사정은 당분간 나아지지 않을 전망입니다.', 'Economy', NOW(), NOW()),
                                                                                ('https://biz.sbs.co.kr/article/1', '전기차 수요 둔화, 배터리 업계 숨고르기', '폭발적으로 성장하던 전기차 시장이 일시적인 수요 정체 구간인 캐즘(Chasm)에 진입했다는 분석이 나오고 있습니다. 충전 인프라 부족과 높은 가격, 보조금 축소 등이 소비자들의 구매를 주저하게 만드는 주요 원인입니다. 이에 따라 국내 배터리 3사는 공격적인 투자 속도를 조절하고 차세대 배터리 기술 개발에 집중하는 등 내실 다지기에 들어갔습니다. 업계는 2~3년 내에 가격 경쟁력을 갖춘 보급형 모델이 출시되면 시장이 다시 반등할 것으로 보고 있습니다.', 'Economy', NOW(), NOW()),
                                                                                ('https://www.economist.com/finance', 'The Future of Digital Currency', '각국 중앙은행이 주도하는 디지털 화폐(CBDC) 도입 논의가 구체화되면서 화폐의 미래에 대한 관심이 뜨겁습니다. CBDC는 기존 화폐 시스템의 효율성을 높이고 금융 포용성을 확대할 수 있는 잠재력을 가지고 있습니다. 하지만 개인 정보 침해와 기존 은행 시스템의 위축 등 해결해야 할 과제도 만만치 않습니다. 주요국들은 시범 사업을 통해 기술적 안정성을 검증하고 법적 기반을 마련하는 데 박차를 가하고 있습니다.', 'Economy', NOW(), NOW()),
                                                                                ('https://www.mk.co.kr/news/stock/2', '공매도 금지 조치 연장, 증시에 미칠 영향', '금융 당국이 공매도 전면 금지 조치를 연장하기로 결정하면서 시장의 반응이 엇갈리고 있습니다. 개인 투자자들은 기울어진 운동장을 바로잡을 기회라며 환영하는 반면, 외국인 투자자들은 시장의 자율성을 해칠 수 있다며 우려를 표하고 있습니다. 공매도 금지 기간 동안 불법 무차입 공매도를 방지할 전산 시스템 구축이 완료될 예정입니다. 이번 조치가 장기적으로 국내 증시의 MSCI 선진국 지수 편입에 어떤 영향을 미칠지 귀추가 주목됩니다.', 'Economy', NOW(), NOW()),
                                                                                ('https://n.news.naver.com/mnews/article/001/4', '국제 유가, 중동 정세 불안에 급등', '중동 지역의 지정학적 리스크가 고조되면서 국제 유가가 배럴당 90달러를 위협하는 등 급등세를 보이고 있습니다. 주요 산유국들의 감산 조치 연장과 맞물려 에너지 공급 부족에 대한 우려가 시장을 지배하고 있습니다. 유가상승은 전 세계적인 인플레이션 압력을 다시 높일 수 있어 각국 중앙은행들의 긴축 기조를 장기화시킬 위험이 있습니다. 에너지 수입 의존도가 높은 한국 경제에도 무역 수지 악화 등 부정적인 영향이 예상됩니다.', 'Economy', NOW(), NOW());
INSERT INTO links (url, title, ai_summary, content, created_at, updated_at) VALUES
                                                                                ('https://www.vogue.co.kr/fashion/trend/1', '2024 SS 패션 트렌드 총정리', '올해 봄/여름 시즌의 런웨이는 화려함보다는 절제된 미니멀리즘이 주를 이루었습니다. 90년대의 향수를 불러일으키는 클린한 실루엣과 모노톤 컬러 팔레트가 트렌드의 중심에 섰습니다. 동시에 시스루 소재를 활용한 레이어드 룩이 등장하여 우아하면서도 관능적인 무드를 더했습니다. 패션 전문가들은 로고를 드러내지 않는 조용한 럭셔리(Quiet Luxury)가 당분간 패션계를 지배할 것으로 전망합니다.', 'Fashion', NOW(), NOW()),
                                                                                ('https://www.elle.co.kr/beauty/skin/1', '환절기 피부 장벽을 지키는 5가지 루틴', '큰 일교차와 건조한 바람으로 인해 피부 장벽이 무너지기 쉬운 환절기에는 세심한 관리가 필요합니다. 피부과 전문의들은 약산성 클렌저 사용과 충분한 보습제 도포를 가장 기본적인 원칙으로 강조합니다. 특히 세라마이드와 판테놀 성분이 함유된 제품은 무너진 장벽을 복구하는 데 탁월한 효과가 있습니다. 또한, 하루 2리터 이상의 물 섭취와 충분한 수면 등 생활 습관의 개선도 병행되어야 합니다.', 'Beauty', NOW(), NOW()),
                                                                                ('https://www.musinsa.com/magazine/coordi/1', '실패 없는 출근룩, 와이드 슬랙스 코디', '편안한 착용감과 세련된 핏을 동시에 잡을 수 있는 와이드 슬랙스는 직장인들의 필수 아이템이 되었습니다. 상의를 슬림하게 매치하여 상하의 밸런스를 맞추거나, 크롭 기장의 자켓을 걸쳐 다리를 더 길어 보이게 하는 것이 스타일링의 핵심입니다. 소재에 따라 린넨은 여름철 쿨비즈 룩으로, 울 소재는 겨울철 포멀 룩으로 활용도가 매우 높습니다. 신발은 스니커즈부터 로퍼까지 다양하게 어울려 코디 고민을 덜어줍니다.', 'Fashion', NOW(), NOW()),
                                                                                ('https://www.allurekorea.com/makeup/1', '퍼스널 컬러별 립스틱 추천 가이드', '자신의 피부 톤에 맞는 립스틱을 선택하는 것만으로도 안색이 환해지고 생기 있어 보이는 효과를 얻을 수 있습니다. 봄 웜톤에게는 화사한 코랄 핑크를, 여름 쿨톤에게는 차분한 로즈 핑크 컬러를 추천합니다. 가을 웜톤은 깊이 있는 벽돌색(MLBB)이, 겨울 쿨톤은 강렬한 레드나 플럼 컬러가 베스트입니다. 매장에서 직접 발색해보고 자연광 아래에서 확인하는 것이 실패 없는 구매 요령입니다.', 'Beauty', NOW(), NOW()),
                                                                                ('https://www.glowpick.com/beauty/ranking/1', '올리브영 랭킹 1위 수분크림 비교 리뷰', '수많은 수분크림 중에서 나에게 딱 맞는 제품을 찾기 위해 실제 사용자들의 리얼 리뷰와 성분을 꼼꼼히 분석했습니다. 1위를 차지한 제품은 히알루론산 복합 성분으로 속건조를 확실하게 잡아주면서도 끈적임 없는 마무리감이 특징입니다. 민감성 피부를 위한 저자극 테스트를 완료했으며, 가성비 또한 훌륭하여 재구매율이 매우 높습니다. 건성부터 지성까지 모든 피부 타입이 부담 없이 사용할 수 있는 데일리 아이템입니다.', 'Beauty', NOW(), NOW()),
                                                                                ('https://www.marieclairekorea.com/fashion/1', '올드머니 룩의 핵심, 로고리스 아이템', '부를 과시하지 않으면서도 고급스러움을 드러내는 올드머니 룩이 MZ세대의 새로운 패션 트렌드로 자리 잡았습니다. 이 스타일의 핵심은 브랜드 로고를 감추고 소재의 퀄리티와 완벽한 핏에 집중하는 것입니다. 캐시미어 니트, 실크 셔츠, 잘 재단된 트렌치코트 등이 대표적인 아이템으로 꼽힙니다. 유행을 타지 않는 클래식한 디자인으로 오래 입을 수 있어 지속 가능한 패션의 일환으로도 주목받고 있습니다.', 'Fashion', NOW(), NOW()),
                                                                                ('https://www.gqkorea.co.kr/grooming/1', '남자를 위한 눈썹 정리 가이드', '눈썹은 남자의 인상을 좌우하는 가장 중요한 요소 중 하나로, 조금만 다듬어도 훨씬 깔끔하고 훈훈한 이미지를 줄 수 있습니다. 눈썹 칼과 가위를 이용해 지저분한 잔털을 정리하고, 빈 곳은 아이브로우 펜슬로 자연스럽게 채워주는 것이 기본입니다. 자신의 얼굴형에 맞춰 일자형이나 아치형 등 적절한 모양을 찾는 것이 중요합니다. 처음이라면 전문 브로우 바를 방문하여 전문가의 도움을 받는 것도 좋은 방법입니다.', 'Beauty', NOW(), NOW()),
                                                                                ('https://www.bazaar.co.kr/fashion/bag/1', '명품 입문자를 위한 클래식 백 추천', '첫 명품 가방을 고민 중이라면 유행을 타지 않고 10년 뒤에도 들 수 있는 클래식한 디자인을 선택하는 것이 현명합니다. 샤넬의 플랩백, 에르메스의 켈리백, 디올의 레이디백 등은 시간이 지날수록 가치가 오르는 타임리스 아이템입니다. 블랙이나 베이지 같은 뉴트럴 컬러를 선택하면 어떤 옷차림에도 무난하게 매치할 수 있습니다. 가방의 소재와 내구성, 수납력 등을 꼼꼼히 따져보고 자신의 라이프스타일에 맞는 제품을 골라야 합니다.', 'Fashion', NOW(), NOW()),
                                                                                ('https://www.musinsa.com/snap/street/1', '성수동 스트릿 패션 스냅 모음', '서울의 핫플레이스 성수동에서 포착한 패션 피플들의 리얼웨이 룩을 통해 최신 트렌드를 엿볼 수 있습니다. 빈티지한 워크웨어부터 개성 넘치는 고프코어 룩까지 다양한 스타일이 공존하며 거리의 활기를 더하고 있습니다. 과감한 컬러 매치와 독특한 액세서리 활용이 돋보이며, 자신만의 개성을 표출하는 데 주저함이 없는 모습입니다. 이번 시즌 유행 아이템을 어떻게 소화했는지 참고하여 나만의 스타일링에 응용해 보세요.', 'Fashion', NOW(), NOW()),
                                                                                ('https://www.vogue.co.kr/beauty/hair/1', '얼굴형에 맞는 단발 헤어스타일 찾기', '단발병을 유발하는 계절, 무작정 자르기보다는 내 얼굴형의 단점을 보완해주는 컷 스타일을 찾는 것이 중요합니다. 둥근 얼굴형은 앞머리 없는 칼단발이나 태슬컷으로 시크한 느낌을 주면 얼굴이 갸름해 보입니다. 긴 얼굴형은 턱선 기장의 레이어드 컷에 볼륨을 넣어주면 시선이 분산되어 단점을 커버할 수 있습니다. 각진 얼굴형은 굵은 웨이브 펌을 더해 부드러운 인상을 연출하는 것을 추천합니다.', 'Beauty', NOW(), NOW()),
                                                                                ('https://www.cosmopolitan.co.kr/fashion/shoes/1', '발이 편한 스니커즈 브랜드 Best 5', '디자인과 착화감을 모두 만족시키는 스니커즈 브랜드를 엄선하여 소개합니다. 쿠션감이 뛰어난 런닝화 기반의 제품부터 인체공학적 설계가 적용된 기능성 슈즈까지 다양한 옵션이 있습니다. 장시간 걸어도 발의 피로도가 적어 여행용이나 데일리 슈즈로 강력 추천합니다. 최근에는 친환경 소재를 사용한 브랜드들도 늘어나고 있어 가치 소비를 지향하는 소비자들에게 좋은 선택지가 되고 있습니다.', 'Fashion', NOW(), NOW()),
                                                                                ('https://www.elle.co.kr/beauty/body/1', '향기 좋은 바디로션으로 힐링하기', '샤워 후 바르는 바디로션의 향기는 지친 하루의 피로를 풀어주는 훌륭한 테라피가 됩니다. 니치 향수 브랜드에서 출시한 바디 제품들은 향수 못지않은 발향력과 지속력을 자랑하며 은은한 살냄새를 만들어줍니다. 보습력은 기본이고 끈적임 없이 산뜻하게 흡수되는 텍스처의 제품들이 인기를 끌고 있습니다. 취향에 맞는 향기를 입고 잠자리에 들면 숙면에도 도움이 됩니다.', 'Beauty', NOW(), NOW()),
                                                                                ('https://www.wmagazine.com/fashion/y2k/1', 'Y2K 패션은 계속된다, 로우라이즈의 매력', '2000년대 초반을 풍미했던 세기말 감성의 Y2K 패션이 젠지 세대를 중심으로 여전히 뜨거운 인기를 누리고 있습니다. 골반에 걸쳐 입는 로우라이즈 팬츠와 짧은 크롭티의 조합은 힙하고 자유분방한 분위기를 연출합니다. 다리가 짧아 보일까 걱정된다면 통굽 부츠나 청키한 스니커즈를 매치하여 비율을 보정할 수 있습니다. 벨벳 트레이닝복, 카고 팬츠 등 다양한 레트로 아이템을 믹스매치하여 나만의 개성을 표현해 보세요.', 'Fashion', NOW(), NOW()),
                                                                                ('https://www.musinsa.com/magazine/brand/1', '떠오르는 디자이너 브랜드 Top 10', '독창적인 디자인 철학으로 무장한 국내 신진 디자이너 브랜드들이 패션계에 신선한 바람을 일으키고 있습니다. 이들은 대량 생산되는 기성복과는 차별화된 디테일과 감성으로 MZ세대 팬덤을 빠르게 구축하고 있습니다. 해외 유명 편집숍에 입점하거나 K-팝 스타들이 착용하면서 글로벌 인지도 또한 높아지는 추세입니다. 남들과 다른 유니크한 스타일을 찾고 있다면 이들 브랜드의 컬렉션을 주목해 볼 필요가 있습니다.', 'Fashion', NOW(), NOW()),
                                                                                ('https://www.allurekorea.com/beauty/nail/1', '집에서 하는 셀프 젤네일 꿀팁', '네일 샵에 가지 않고도 집에서 전문가 수준의 젤 네일을 완성할 수 있는 노하우를 공개합니다. 손톱 유분기 제거와 베이스 젤 도포 등 기초 공사를 꼼꼼히 해야 유지력을 높일 수 있습니다. 얇게 여러 번 발라 큐어링하는 것이 매끈한 표면을 만드는 비결이며, 탑 젤로 꼼꼼히 마무리해야 광택이 오래갑니다. 다양한 컬러와 파츠를 활용해 기분 전환을 하고 나만의 네일 아트를 즐겨보세요.', 'Beauty', NOW(), NOW());
INSERT INTO links (url, title, ai_summary, content, created_at, updated_at) VALUES
                                                                                ('https://www.10000recipe.com/recipe/1', '자취생 필수, 스팸 김치볶음밥 황금레시피', '특별한 반찬 없이도 한 그릇 뚝딱 비울 수 있는 김치볶음밥의 맛을 업그레이드하는 비법을 소개합니다. 파기름을 내어 풍미를 살리고, 김치를 볶을 때 설탕을 넣어 신맛을 중화시키는 것이 포인트입니다. 마지막에 굴소스나 간장을 살짝 눌려 불맛을 입히면 식당에서 먹는 것 같은 감칠맛을 낼 수 있습니다. 반숙 계란 프라이와 김 가루를 곁들이면 완벽한 한 끼 식사가 완성됩니다.', 'Cooking', NOW(), NOW()),
                                                                                ('https://www.youtube.com/watch?v=cooking1', '백종원의 만능 양념장 만들기', '냉장고에 만들어 두면 볶음, 조림, 찌개 등 어떤 요리에도 활용 가능한 백종원표 만능 양념장 레시피입니다. 고추장, 고춧가루, 설탕, 간장 등을 황금 비율로 배합하여 숙성시키면 깊은 맛이 우러납니다. 바쁜 평일 저녁, 재료만 손질해서 이 양념장만 넣고 볶으면 10분 만에 근사한 메인 요리가 탄생합니다. 요리 초보자도 실패 없이 맛을 낼 수 있는 치트키와 같은 아이템입니다.', 'Cooking', NOW(), NOW()),
                                                                                ('https://www.kurly.com/goods/1', '마켓컬리 추천템, 이베리코 목살 스테이크', '세계 4대 진미로 꼽히는 이베리코 흑돼지 목살을 집에서 간편하게 즐길 수 있는 밀키트 제품입니다. 풍부한 마블링과 고소한 육즙이 특징이며, 잡내 없이 부드러운 식감을 자랑합니다. 동봉된 허브 솔트와 올리브 오일로 마리네이드한 뒤 센 불에 빠르게 구워내면 레스토랑 스테이크 못지않은 퀄리티를 맛볼 수 있습니다. 특별한 날 홈파티 메뉴나 캠핑 요리로 강력 추천합니다.', 'Cooking', NOW(), NOW()),
                                                                                ('https://brunch.co.kr/@cook/1', '주말 아침을 여는 브런치 메뉴 3가지', '늦잠 자고 일어난 주말 아침, 여유롭게 즐기기 좋은 홈 브런치 레시피 3가지를 제안합니다. 폭신한 프렌치 토스트, 수란을 곁들인 에그 베네딕트, 신선한 샐러드 파스타가 그 주인공입니다. 예쁜 접시에 담아내고 향긋한 커피 한 잔을 곁들이면 유명 브런치 카페가 부럽지 않습니다. 사랑하는 가족, 연인과 함께 만드는 즐거움과 맛있는 행복을 느껴보세요.', 'Cooking', NOW(), NOW()),
                                                                                ('https://www.10000recipe.com/recipe/2', '실패 없는 소고기 미역국 끓이는 법', '생일상에 빠질 수 없는 소고기 미역국을 깊고 진하게 끓이는 정석 레시피를 알려드립니다. 소고기와 불린 미역을 참기름에 충분히 볶아주는 것이 국물 맛의 핵심입니다. 쌀뜨물을 사용하면 구수함이 배가되며, 액젓으로 간을 맞추면 감칠맛이 살아납니다. 끓이면 끓일수록 맛이 깊어지므로 넉넉하게 끓여두고 든든한 아침 식사로 챙겨 먹기 좋습니다.', 'Cooking', NOW(), NOW()),
                                                                                ('https://www.youtube.com/watch?v=baking1', '노오븐 디저트, 전자레인지 초코케이크', '복잡한 베이킹 도구나 오븐 없이도 전자레인지로 5분 만에 만들 수 있는 초간단 초코케이크입니다. 핫케이크 가루와 코코아 파우더, 우유만 있으면 누구나 쉽게 따라 할 수 있습니다. 꾸덕꾸덕한 식감과 진한 초콜릿 풍미가 스트레스를 한 방에 날려줍니다. 아이들과 함께 만드는 요리 활동으로도 좋으며, 당 충전이 필요한 오후 간식으로 안성맞춤입니다.', 'Cooking', NOW(), NOW()),
                                                                                ('https://blog.naver.com/foodie/1', '서울 3대 평양냉면 맛집 투어', '평양냉면 마니아라면 꼭 가봐야 할 서울의 대표적인 노포 3곳을 직접 방문하고 비교 분석했습니다. 맑고 육향 진한 육수와 툭툭 끊어지는 메밀면의 조화가 각 식당마다 어떤 차이가 있는지 상세히 묘사했습니다. 처음에는 슴슴하게 느껴질 수 있지만 먹을수록 중독되는 평양냉면만의 매력을 심도 있게 다룹니다. 긴 웨이팅을 감수하고서라도 먹을 가치가 있는 맛의 세계로 여러분을 초대합니다.', 'Cooking', NOW(), NOW()),
                                                                                ('https://www.kurly.com/magazine/1', '치즈 덕후를 위한 와인 페어링 가이드', '다양한 치즈의 종류와 그에 어울리는 와인 조합을 소개하여 홈술의 품격을 높여드립니다. 크리미한 까망베르 치즈는 샴페인과, 짭짤한 블루치즈는 달콤한 디저트 와인과 환상의 궁합을 자랑합니다. 고소한 하드 치즈는 바디감이 있는 레드 와인과 매치하면 풍미가 더욱 살아납니다. 치즈 플레이팅 팁과 남은 치즈 보관법까지 알찬 정보를 담았습니다.', 'Cooking', NOW(), NOW()),
                                                                                ('https://www.10000recipe.com/recipe/3', '매콤달콤 국민 간식 떡볶이 만들기', '학교 앞 분식집에서 먹던 추억의 떡볶이 맛을 집에서 재현하는 황금 비율 양념장을 공개합니다. 멸치 육수를 사용하면 감칠맛이 돌고, 카레 가루를 한 스푼 넣으면 독특한 풍미가 더해집니다. 밀떡과 쌀떡 중 취향에 맞는 떡을 선택하고, 어묵과 대파를 듬뿍 넣어 푸짐하게 즐겨보세요. 라면 사리나 삶은 달걀, 튀김을 곁들이면 한 끼 식사로도 손색이 없습니다.', 'Cooking', NOW(), NOW()),
                                                                                ('https://www.youtube.com/watch?v=pasta1', '원팬으로 끝내는 알리오 올리오 파스타', '면을 따로 삶을 필요 없이 프라이팬 하나로 모든 조리 과정을 끝내는 초간단 원팬 파스타 레시피입니다. 마늘과 페페론치노를 올리브 오일에 볶아 향을 내고, 물과 면을 넣어 자작하게 끓여내면 유화가 잘 되어 소스가 착 감깁니다. 설거지거리가 줄어들어 자취생이나 요리가 귀찮은 날에 활용하기 좋습니다. 간단하지만 맛은 이탈리안 레스토랑 못지않은 퀄리티를 보장합니다.', 'Cooking', NOW(), NOW()),
                                                                                ('https://brunch.co.kr/@dietfood/1', '살 안 찌는 다이어트 키토 김밥 레시피', '탄수화물인 밥 대신 계란 지단이나 두부를 넣어 만든 저탄고지 키토 김밥은 다이어터들에게 인기 만점입니다. 당근, 시금치, 단무지 등 채소를 듬뿍 넣어 아삭한 식감과 포만감을 동시에 잡았습니다. 김밥을 마는 것이 어렵다면 샌드위치처럼 접어 먹는 사각 김밥으로 응용할 수도 있습니다. 맛있는 것을 먹으면서도 건강하게 체중 관리를 하고 싶은 분들에게 강력 추천하는 메뉴입니다.', 'Cooking', NOW(), NOW()),
                                                                                ('https://www.bluebottlecoffeekorea.com/brew', '핸드드립 커피, 물 온도가 맛을 좌우한다', '원두의 종류와 로스팅 정도에 따라 최적의 물 온도가 다르다는 사실을 알고 계셨나요? 일반적으로 약배전 원두는 높은 온도에서, 강배전 원두는 낮은 온도에서 추출해야 쓴맛을 줄이고 본연의 향미를 살릴 수 있습니다. 집에서도 전문 바리스타처럼 맛있는 핸드드립 커피를 내리기 위한 물 온도 조절 노하우와 추출 팁을 상세히 알려드립니다. 커피 한 잔에 담긴 과학과 미학을 경험해 보세요.', 'Cooking', NOW(), NOW()),
                                                                                ('https://www.10000recipe.com/recipe/4', '비 오는 날 생각나는 바삭한 김치전', '비 오는 날이면 어김없이 생각나는 김치전을 바삭하게 부쳐내는 비법을 전수합니다. 부침가루와 튀김가루를 섞어 반죽하고, 차가운 물이나 탄산수를 사용하면 튀김처럼 바삭한 식감을 낼 수 있습니다. 잘 익은 김치와 오징어, 돼지고기를 썰어 넣고 기름을 넉넉히 두른 팬에 튀기듯 구워내세요. 막걸리 한 잔과 함께 곁들이면 세상 부러울 것 없는 행복한 야식 타임이 됩니다.', 'Cooking', NOW(), NOW()),
                                                                                ('https://www.youtube.com/watch?v=steak1', '집에서 스테이크 완벽하게 굽는 법', '집에서도 겉은 바삭하고 속은 촉촉한 스테이크를 굽기 위해서는 마이야르 반응을 이해하는 것이 중요합니다. 고기 표면의 물기를 제거하고 뜨겁게 달군 팬에 시어링하여 육즙을 가두는 것이 핵심 테크닉입니다. 고기를 구운 후 레스팅 시간을 거치면 육즙이 골고루 퍼져 더욱 부드러운 맛을 즐길 수 있습니다. 버터와 허브로 풍미를 더하는 아로제 과정까지 마스터하여 홈스토랑을 열어보세요.', 'Cooking', NOW(), NOW()),
                                                                                ('https://www.kurly.com/goods/2', '그릭요거트 맛있게 먹는 토핑 조합', '꾸덕꾸덕한 식감과 담백한 맛이 일품인 그릭요거트를 더욱 맛있고 건강하게 즐기는 다양한 토핑 조합을 소개합니다. 바삭한 그래놀라와 견과류, 달콤한 꿀이나 메이플 시럽은 가장 클래식하면서도 실패 없는 조합입니다. 제철 과일이나 콤포트를 곁들이면 상큼함이 더해져 디저트로도 손색이 없습니다. 베이글이나 통밀빵에 크림치즈 대신 발라 먹으면 든든하고 건강한 아침 식사가 됩니다.', 'Cooking', NOW(), NOW());
INSERT INTO links (url, title, ai_summary, content, created_at, updated_at) VALUES
                                                                                ('https://www.healthline.com/nutrition/1', '간헐적 단식, 16:8 방법의 효과와 주의점', '하루 중 16시간 동안 공복을 유지하고 8시간 동안만 식사하는 16:8 간헐적 단식은 체중 감량과 대사 건강 개선에 효과적입니다. 공복 상태에서 인슐린 수치가 낮아지면 지방 연소가 촉진되고, 세포 자가 포식(Autophagy) 작용이 활성화되어 노화를 늦추는 효과도 있습니다. 하지만 식사 시간에 폭식을 하거나 영양 불균형이 생기지 않도록 주의해야 합니다. 자신의 라이프스타일에 맞춰 무리하지 않게 시작하는 것이 지속 가능한 단식의 핵심입니다.', 'Health', NOW(), NOW()),
                                                                                ('https://www.youtube.com/watch?v=physical1', '거북목 교정하는 하루 5분 스트레칭', '장시간 스마트폰과 컴퓨터 사용으로 인해 앞으로 굽은 거북목을 교정해주는 간단하면서도 효과적인 스트레칭 루틴입니다. 흉쇄유돌근과 승모근을 이완시키고, 약해진 목 뒤쪽 근육을 강화하여 바른 자세를 되찾아줍니다. 매일 꾸준히 따라 하면 목과 어깨의 통증이 줄어들고 두통 완화에도 도움이 됩니다. 직장인이나 학생들이 사무실이나 책상 앞에서 틈틈이 실천하기 좋은 동작들로 구성되어 있습니다.', 'Health', NOW(), NOW()),
                                                                                ('https://www.nike.com/running/guide', '러닝 초보자를 위한 올바른 달리기 자세', '달리기는 가장 접근하기 쉬운 운동이지만, 잘못된 자세로 달리면 무릎이나 발목 부상의 위험이 큽니다. 시선은 전방을 향하고 상체는 곧게 펴며, 발은 몸의 무게 중심 아래에 착지하는 미드풋 주법을 익히는 것이 좋습니다. 호흡은 코와 입을 모두 사용하여 편안하고 규칙적으로 유지해야 합니다. 자신에게 맞는 러닝화를 선택하고, 달리기 전후로 충분한 스트레칭을 해주는 것도 잊지 마세요.', 'Health', NOW(), NOW()),
                                                                                ('https://www.webmd.com/sleep/1', '잠이 보약, 수면의 질을 높이는 습관', '충분하고 질 좋은 수면은 신체 회복과 면역력 강화, 뇌 기능 유지에 필수적인 요소입니다. 규칙적인 수면 시간을 지키고, 잠들기 전 스마트폰 사용을 자제하여 멜라토닌 분비를 방해하지 않도록 해야 합니다. 침실은 어둡고 조용하며 서늘하게 유지하는 것이 숙면에 도움이 됩니다. 낮 동안 햇빛을 쬐고 가벼운 운동을 하는 것도 밤에 잠을 잘 오게 하는 좋은 습관입니다.', 'Health', NOW(), NOW()),
                                                                                ('https://www.youtube.com/watch?v=yoga1', '아침을 깨우는 전신 순환 요가 10분', '무거운 몸과 마음을 개운하게 깨워주는 아침 요가는 하루의 활력을 충전하는 최고의 방법입니다. 굳어있던 관절과 근육을 부드럽게 풀어주는 스트레칭 동작들은 혈액 순환을 돕고 붓기를 제거하는 데 효과적입니다. 호흡에 집중하며 내면을 바라보는 시간은 스트레스를 낮추고 긍정적인 마인드를 심어줍니다. 단 10분의 투자로 상쾌하고 에너지 넘치는 하루를 시작해 보세요.', 'Health', NOW(), NOW()),
                                                                                ('https://www.health.com/fitness/squat', '스쿼트, 무릎 통증 없이 하는 법', '하체 운동의 꽃이라 불리는 스쿼트는 엉덩이와 허벅지 근육을 강화하는 최고의 운동이지만, 자세가 바르지 않으면 무릎 부상을 유발할 수 있습니다. 무릎이 발끝보다 너무 많이 나가지 않도록 주의하고, 엉덩이를 뒤로 빼면서 앉는 힙 힌지 동작을 정확히 수행해야 합니다. 허리가 말리지 않도록 복부에 힘을 주고, 발바닥 전체로 지면을 밀어내는 느낌으로 일어나는 것이 포인트입니다. 맨몸으로 정확한 자세를 익힌 후 중량을 추가하는 것이 좋습니다.', 'Health', NOW(), NOW()),
                                                                                ('https://www.medipana.com/news/1', '비타민D 결핍이 면역력에 미치는 영향', '현대인의 대부분이 겪고 있는 비타민D 결핍은 뼈 건강뿐만 아니라 면역 체계 약화와 우울증의 원인이 될 수 있습니다. 비타민D는 햇빛을 통해 피부에서 합성되지만, 실내 생활이 많은 현대인들은 식품이나 영양제를 통해 보충해주는 것이 필요합니다. 연어, 고등어, 버섯 등에 풍부하게 함유되어 있으며, 하루 15분 이상 햇볕을 쬐는 것도 도움이 됩니다. 정기적인 혈액 검사를 통해 자신의 수치를 확인하고 적절한 용량을 섭취하세요.', 'Health', NOW(), NOW()),
                                                                                ('https://www.youtube.com/watch?v=abs1', '뱃살 태우는 고강도 복근 운동 루틴', '단기간에 뱃살을 빼고 탄탄한 복근을 만들고 싶다면 유산소와 근력 운동이 결합된 고강도 인터벌 트레이닝(HIIT)을 추천합니다. 크런치, 레그 레이즈, 플랭크 등 다양한 복근 운동을 휴식 없이 이어서 수행하면 칼로리 소모를 극대화할 수 있습니다. 복부에 지속적인 자극을 주어 코어 근육을 강화하고 체지방을 효과적으로 연소시킵니다. 꾸준한 운동과 함께 식단 조절을 병행하면 11자 복근의 꿈을 이룰 수 있습니다.', 'Health', NOW(), NOW()),
                                                                                ('https://www.mindful.org/meditation', '스트레스 해소를 위한 마인드풀니스 명상', '바쁜 일상 속에서 스트레스와 불안을 다스리기 위해 현재의 순간에 온전히 집중하는 마음챙김(Mindfulness) 명상이 주목받고 있습니다. 편안한 자세로 앉아 호흡의 드나듦을 관찰하고, 떠오르는 생각이나 감정을 판단 없이 바라보는 연습을 해보세요. 하루 5분 명상은 뇌의 구조를 긍정적으로 변화시키고 감정 조절 능력을 향상시킵니다. 명상은 마음의 근육을 키우는 훈련이자 나를 돌보는 소중한 시간입니다.', 'Health', NOW(), NOW()),
                                                                                ('https://www.healthline.com/nutrition/protein', '근성장에 필요한 단백질 섭취 타이밍', '근육을 키우기 위해서는 운동 강도만큼이나 단백질 섭취 타이밍과 양이 중요합니다. 운동 직후 30분에서 1시간 이내인 기회의 창에 단백질을 섭취하면 근육 합성이 가장 활발하게 일어납니다. 닭가슴살, 달걀, 프로틴 쉐이크 등 양질의 단백질을 체중 1kg당 1.6~2.2g 정도 섭취하는 것이 권장됩니다. 한 번에 많이 먹기보다는 3~4시간 간격으로 나누어 섭취하는 것이 체내 흡수율을 높이는 방법입니다.', 'Health', NOW(), NOW()),
                                                                                ('https://www.youtube.com/watch?v=stretching1', '다리 붓기 빼는 폼롤러 마사지법', '하루 종일 서 있거나 앉아 있어서 퉁퉁 부은 다리를 방치하면 하지 정맥류나 하체 비만으로 이어질 수 있습니다. 폼롤러를 이용하여 종아리, 허벅지, 엉덩이 근육을 롤링해주면 림프 순환을 돕고 뭉친 근막을 이완시켜 붓기 제거에 탁월합니다. 특히 겨드랑이나 서혜부 림프절을 자극해주면 노폐물 배출 효과가 배가됩니다. TV를 보면서 매일 저녁 10분만 투자해도 가볍고 날씬한 다리 라인을 만들 수 있습니다.', 'Health', NOW(), NOW()),
                                                                                ('https://www.nike.com/training/home', '층간소음 없는 전신 유산소 홈트', '아파트나 다세대 주택에서도 층간소음 걱정 없이 땀을 낼 수 있는 전신 유산소 운동 루틴을 소개합니다. 점프 동작을 배제하고 스쿼트, 런지, 슬로우 버피 등 근력을 동반한 동작들로 구성하여 칼로리 소모를 높였습니다. 매트를 깔고 동작을 부드럽게 연결하면 소음은 줄이면서 운동 효과는 확실하게 얻을 수 있습니다. 날씨나 시간에 구애받지 않고 집에서 건강을 챙겨보세요.', 'Health', NOW(), NOW()),
                                                                                ('https://www.webmd.com/diet/sugar', '설탕 중독에서 벗어나는 식단 관리법', '과도한 설탕 섭취는 비만, 당뇨병, 피부 노화 등 만병의 근원이 되므로 의식적으로 줄이려는 노력이 필요합니다. 가공식품이나 탄산음료 대신 신선한 과일이나 채소를 섭취하고, 요리할 때는 설탕 대신 알룰로스나 스테비아 같은 대체 감미료를 활용하세요. 영양 성분표를 확인하는 습관을 들이고, 숨겨진 당분을 찾아내는 것이 중요합니다. 단맛에 길들여진 입맛을 바꾸면 몸이 가벼워지고 컨디션이 좋아지는 것을 느낄 수 있습니다.', 'Health', NOW(), NOW()),
                                                                                ('https://www.youtube.com/watch?v=backpain1', '허리 통증 잡는 맥켄지 신전 운동', '허리 디스크나 만성 요통으로 고생하는 분들에게 물리치료사들이 추천하는 맥켄지 신전 운동입니다. 엎드린 자세에서 상체를 천천히 들어 올려 허리를 뒤로 젖히는 동작은 디스크가 제자리로 돌아가도록 돕습니다. 통증이 없는 범위 내에서 진행해야 하며, 다리 저림 증상이 나타나면 즉시 중단해야 합니다. 평소 바른 자세를 유지하고 허리 근육을 강화하는 코어 운동을 병행하면 통증 재발을 막을 수 있습니다.', 'Health', NOW(), NOW()),
                                                                                ('https://www.health.com/mental/burnout', '직장인 번아웃 증후군 자가 진단', '과도한 업무와 스트레스로 인해 신체적, 정신적 에너지가 고갈되는 번아웃 증후군은 현대 직장인들의 고질병입니다. 만성 피로, 무기력증, 업무 효율 저하, 냉소적인 태도 등이 나타난다면 번아웃을 의심해봐야 합니다. 휴식을 죄악시하지 말고 충분한 수면과 취미 생활을 통해 재충전의 시간을 갖는 것이 중요합니다. 완벽주의 성향을 내려놓고 동료나 전문가에게 도움을 요청하는 용기도 필요합니다.', 'Health', NOW(), NOW());
INSERT INTO links (url, title, ai_summary, content, created_at, updated_at) VALUES
                                                                                ('https://ko.wikipedia.org/wiki/Renaissance', '르네상스, 인간 중심 사상의 부활', '중세의 신 중심적 세계관에서 벗어나 인간의 존엄성과 가치를 재발견하고자 했던 르네상스는 근대 유럽 문화의 태동이 된 혁명적인 시기였습니다. 14세기 이탈리아에서 시작된 이 흐름은 문학, 예술, 과학 등 다양한 분야에서 찬란한 발전을 이룩했습니다. 레오나르도 다 빈치, 미켈란젤로 등 천재적인 예술가들은 인체와 자연을 사실적으로 묘사하며 인간성의 아름다움을 찬미했습니다. 르네상스 인문주의는 개인의 이성과 자유 의지를 강조하며 종교 개혁과 과학 혁명의 토대를 마련했습니다.', 'Humanities', NOW(), NOW()),
                                                                                ('https://brunch.co.kr/@psychology/1', '자존감과 나르시시즘의 미묘한 차이', '자신을 사랑하는 마음인 자존감과 자기애성 인격 장애인 나르시시즘은 겉보기에 비슷해 보이지만 근본적인 차이가 있습니다. 자존감이 높은 사람은 자신의 약점까지 수용하고 타인을 존중하는 반면, 나르시시스트는 내면의 열등감을 감추기 위해 과도하게 우월감을 과시하고 타인을 착취하려 합니다. 건강한 자존감은 타인의 평가에 휘둘리지 않는 단단한 내면에서 비롯됩니다. 자신을 객관적으로 바라보고 있는 그대로 받아들이는 연습이 필요합니다.', 'Humanities', NOW(), NOW()),
                                                                                ('https://www.ted.com/talks/1', '우리는 왜 잠을 자야 할까요?', '수면은 단순히 쉬는 시간이 아니라 뇌가 낮 동안 습득한 정보를 정리하고 독소를 배출하는 매우 활동적인 과정입니다. 수면 부족은 기억력 감퇴, 집중력 저하뿐만 아니라 알츠하이머병과 같은 퇴행성 뇌 질환의 위험을 높일 수 있습니다. 꿈을 꾸는 렘수면 단계에서는 창의적인 문제 해결 능력과 감정 조절 기능이 강화됩니다. 인생의 3분의 1을 차지하는 잠은 깨어있는 삶의 질을 결정하는 가장 중요한 요소입니다.', 'Humanities', NOW(), NOW()),
                                                                                ('https://terms.naver.com/entry/1', '양자역학의 세계, 슈뢰딩거의 고양이', '상자 속의 고양이가 살아있으면서 동시에 죽어있다는 슈뢰딩거의 고양이 사고 실험은 양자역학의 중첩 원리를 설명하는 가장 유명한 예시입니다. 미시 세계의 입자들은 관측하기 전까지는 여러 상태가 확률적으로 공존하다가, 관측하는 순간 하나의 상태로 결정된다는 난해한 개념을 담고 있습니다. 이는 우리의 직관과 상식을 뒤흔들며 우주의 본질에 대한 철학적인 질문을 던집니다. 양자역학은 현대 물리학의 기반이 되어 반도체, 레이저 등 첨단 기술의 발전을 이끌었습니다.', 'Humanities', NOW(), NOW()),
                                                                                ('https://brunch.co.kr/@history/1', '조선왕조실록에 기록된 기이한 사건들', '유네스코 세계기록유산인 조선왕조실록에는 엄격한 역사적 사실 외에도 UFO 목격담이나 기이한 자연 현상 등 미스터리한 기록들이 다수 존재합니다. 광해군 일기에 기록된 화가 투구 모양의 비행 물체나, 정조 때 나타난 정체불명의 짐승 등은 당대 사람들의 상상력과 두려움을 보여주는 흥미로운 사료입니다. 이러한 기록들은 단순한 미신으로 치부하기보다는 당시의 사회적 분위기와 자연관을 이해하는 단서가 됩니다. 역사는 승자의 기록이지만, 그 이면에는 설명할 수 없는 수많은 이야기들이 숨겨져 있습니다.', 'Humanities', NOW(), NOW()),
                                                                                ('https://www.art-insight.co.kr/news/1', '인상파 화가들, 빛을 그리는 사람들', '19세기 후반 프랑스에서 등장한 인상파는 사물의 고유한 색을 부정하고 시시각각 변하는 빛과 대기의 효과를 포착하려 했습니다. 모네, 르누아르 등 인상파 화가들은 야외로 캔버스를 들고나가 자연의 생생한 순간을 빠른 붓터치로 담아냈습니다. 그들은 전통적인 회화 기법을 거부하고 색채 분할법을 사용하여 그림에 율동감과 생동감을 불어넣었습니다. 인상파의 혁신적인 시도는 현대 미술의 문을 여는 결정적인 계기가 되었습니다.', 'Humanities', NOW(), NOW()),
                                                                                ('https://ko.wikipedia.org/wiki/Sapiens', '유발 하라리의 사피엔스 요약', '유발 하라리는 저서 <사피엔스>를 통해 변방의 유인원이었던 호모 사피엔스가 어떻게 지구의 지배자가 되었는지 거시적인 관점에서 조망합니다. 그는 인지 혁명, 농업 혁명, 과학 혁명이라는 세 가지 대전환을 통해 인류의 역사를 설명합니다. 특히 보이지 않는 것을 믿고 이야기하는 능력인 상상의 질서가 인간을 대규모로 협력하게 만든 원동력이라고 주장합니다. 이 책은 인류의 과거를 통해 현재를 진단하고 미래를 예측하는 통찰력을 제공합니다.', 'Humanities', NOW(), NOW()),
                                                                                ('https://brunch.co.kr/@philosophy/1', '니체의 신은 죽었다, 그 참된 의미', '프리드리히 니체의 "신은 죽었다"라는 선언은 단순히 종교적인 비판을 넘어 절대적인 가치와 진리가 사라진 허무주의 시대를 예견한 것입니다. 그는 기존의 도덕관념에 얽매이지 않고 자신의 삶을 스스로 긍정하며 새로운 가치를 창조하는 초인(위버멘쉬)이 될 것을 주문했습니다. 영원회귀 사상은 매 순간을 영원히 반복되어도 좋을 만큼 치열하고 주체적으로 살라는 삶의 태도를 강조합니다. 니체의 철학은 현대인들에게 삶의 의미를 묻는 강력한 화두를 던집니다.', 'Humanities', NOW(), NOW()),
                                                                                ('https://www.ted.com/talks/2', '행복은 어디에서 오는가?', '하버드 대학교에서 75년간 진행된 성인 발달 연구는 인간의 행복과 건강을 결정하는 가장 중요한 요인이 무엇인지 밝혀냈습니다. 부나 명예, 학벌보다는 가족, 친구, 공동체와의 따뜻하고 친밀한 관계가 행복한 삶의 핵심 조건임이 증명되었습니다. 고립은 흡연이나 알코올 중독만큼이나 건강에 해로우며 뇌 기능을 저하시킵니다. 진정한 행복은 특별한 사건이 아니라 일상의 소소한 관계를 가꾸는 데 있습니다.', 'Humanities', NOW(), NOW()),
                                                                                ('https://terms.naver.com/entry/2', '행동경제학, 인간은 합리적이지 않다', '전통 경제학은 인간을 합리적인 선택을 하는 존재로 가정하지만, 행동경제학은 인간이 감정과 심리에 휘둘리는 제한된 합리성을 가진 존재라고 봅니다. 손실 회피 편향, 닻 내림 효과 등 다양한 심리적 기제들이 우리의 경제적 의사결정에 어떻게 영향을 미치는지 설명합니다. 리처드 탈러의 넛지 이론은 타인의 선택을 강요하지 않고 부드럽게 개입하여 더 좋은 결과를 유도할 수 있음을 보여줍니다. 행동경제학은 마케팅과 공공 정책 등 다양한 분야에서 활용되고 있습니다.', 'Humanities', NOW(), NOW()),
                                                                                ('https://brunch.co.kr/@bookclub/1', '지금 다시 읽어야 할 고전 문학 5선', '시대를 초월하여 사랑받는 고전 문학은 인간 본성에 대한 깊은 통찰과 삶의 지혜를 담고 있습니다. 도스토옙스키의 <죄와 벌>, 오웰의 <1984>, 헤세의 <데미안> 등은 읽을 때마다 새로운 감동과 깨달음을 주는 명작들입니다. 고전은 복잡한 현대 사회를 살아가는 우리에게 나침반이 되어주며 사유의 폭을 넓혀줍니다. 바쁜 일상 속에서도 고전을 읽는 시간은 영혼을 살찌우는 가장 풍요로운 투자입니다.', 'Humanities', NOW(), NOW()),
                                                                                ('https://www.ted.com/talks/3', 'AI 시대, 인간의 창의성은 대체될까?', '인공지능이 시를 쓰고 그림을 그리는 시대가 도래하면서 인간 고유의 영역이라 여겨졌던 창의성마저 위협받고 있다는 우려가 나옵니다. 하지만 AI는 방대한 데이터를 학습하고 조합하는 데 뛰어날 뿐, 인간처럼 감정을 느끼거나 직관적인 영감을 얻지는 못합니다. 진정한 창의성은 공감 능력과 맥락을 이해하는 힘에서 나오며, 이는 AI가 쉽게 모방할 수 없는 인간만의 강점입니다. AI를 도구로 활용하여 창의성을 확장하는 공존의 지혜가 필요합니다.', 'Humanities', NOW(), NOW()),
                                                                                ('https://ko.wikipedia.org/wiki/Industrial_Revolution', '4차 산업혁명과 미래 사회의 변화', '인공지능, 사물인터넷, 빅데이터 등 디지털 기술이 물리적, 생물학적 영역과 융합하는 4차 산업혁명은 우리 삶의 방식을 근본적으로 바꾸고 있습니다. 초연결, 초지능 사회로의 진입은 생산성을 비약적으로 높이고 새로운 비즈니스 모델을 창출할 것입니다. 하지만 일자리 감소, 양극화 심화, 윤리적 딜레마 등 해결해야 할 사회적 과제들도 산적해 있습니다. 기술의 발전이 인간의 행복에 기여할 수 있도록 사회적 합의와 제도적 장치가 마련되어야 합니다.', 'Humanities', NOW(), NOW()),
                                                                                ('https://brunch.co.kr/@art/1', '현대 미술은 왜 난해할까?', '변기를 미술관에 전시한 마르셀 뒤샹의 <샘> 이후, 현대 미술은 아름다움을 재현하는 것에서 벗어나 작가의 아이디어와 철학을 표현하는 개념 미술로 확장되었습니다. 난해해 보이는 추상화나 설치 미술은 관객에게 정해진 답을 주지 않고 스스로 생각하고 해석하게 만듭니다. 작품 그 자체보다는 작품을 둘러싼 담론과 맥락이 중요해진 것입니다. 열린 마음으로 작품과 소통하고 나만의 감상을 즐기는 것이 현대 미술을 이해하는 첫걸음입니다.', 'Humanities', NOW(), NOW()),
                                                                                ('https://terms.naver.com/entry/3', '그리스 로마 신화의 상징과 해석', '서양 문화의 원류인 그리스 로마 신화는 단순한 옛날이야기가 아니라 인간의 심리와 운명, 자연의 섭리를 은유적으로 담고 있는 거대한 상징 체계입니다. 신들의 사랑과 질투, 모험과 복수 이야기는 인간사의 희로애락을 거울처럼 비춰줍니다. 프로이트와 융 등 심리학자들은 신화를 통해 무의식의 세계를 탐구하기도 했습니다. 신화를 읽는 것은 인간 존재의 근원을 탐구하고 인문학적 상상력을 키우는 흥미로운 여정입니다.', 'Humanities', NOW(), NOW());
INSERT INTO links (url, title, ai_summary, content, created_at, updated_at) VALUES
                                                                                ('https://www.linkedin.com/pulse/1', '성공적인 이직을 위한 링크드인 프로필 팁', '글로벌 비즈니스 인맥 사이트인 링크드인은 이제 이직과 채용의 필수 플랫폼이 되었습니다. 헤드헌터의 눈길을 사로잡기 위해서는 직무와 관련된 키워드를 적절히 사용하여 프로필을 검색에 최적화해야 합니다. 자신의 성과를 구체적인 수치로 보여주는 경력 기술서와 동료들의 추천사는 신뢰도를 높여줍니다. 활발한 인맥 교류와 업계 관련 포스팅 활동은 자신의 전문성을 알리는 좋은 방법입니다.', 'Career', NOW(), NOW()),
                                                                                ('https://www.wanted.co.kr/events/resume', '서류 합격률을 높이는 이력서 작성법', '채용 담당자는 이력서를 검토하는 데 평균 10초도 쓰지 않는다는 사실을 기억해야 합니다. 지원하는 직무와 가장 관련성 높은 경험을 상단에 배치하고, 가독성을 높이는 레이아웃을 사용하는 것이 중요합니다. 단순히 업무 내용을 나열하기보다는 내가 기여한 성과와 문제 해결 과정을 구체적인 에피소드로 보여줘야 합니다. 맞춤법 검사와 오타 확인은 기본 중의 기본이며, PDF로 변환하여 제출하는 것이 안전합니다.', 'Career', NOW(), NOW()),
                                                                                ('https://velog.io/@dev/1', '주니어 개발자가 알아야 할 클린 코드', '코드는 컴퓨터가 실행하지만 읽는 것은 사람이라는 점을 명심해야 합니다. 변수명과 함수명은 의도가 명확하게 드러나도록 짓고, 하나의 함수는 하나의 기능만 수행하도록 작게 쪼개는 것이 좋습니다. 주석에 의존하기보다는 코드 자체로 설명이 되도록 작성하는 것이 클린 코드의 핵심입니다. 코드 리뷰를 통해 동료들의 피드백을 적극적으로 수용하고 리팩토링을 생활화하면 실력 향상에 큰 도움이 됩니다.', 'Career', NOW(), NOW()),
                                                                                ('https://programmers.co.kr/learn', '코딩테스트 고득점을 위한 알고리즘 공부 순서', '개발자 취업의 첫 관문인 코딩테스트를 효율적으로 준비하기 위해서는 체계적인 학습 전략이 필요합니다. 스택, 큐, 정렬 등 기본 자료구조를 먼저 마스터하고, 탐색(BFS/DFS), 동적 계획법(DP) 등 빈출 알고리즘 유형을 익혀야 합니다. 쉬운 문제부터 시작하여 점차 난이도를 높여가며 문제 해결 능력을 키우는 것이 좋습니다. 한 문제를 풀더라도 다양한 풀이 방법을 고민해보고 최적화하는 습관을 들이세요.', 'Career', NOW(), NOW()),
                                                                                ('https://www.youtube.com/watch?v=eo1', '토스 PO가 말하는 프로덕트 오너의 역할', '미니 CEO라고 불리는 프로덕트 오너(PO)는 제품의 비전을 수립하고 실행을 총괄하는 중요한 역할을 맡습니다. 고객의 목소리에 귀 기울여 진짜 문제를 정의하고, 데이터에 기반한 의사결정으로 제품을 고도화시켜야 합니다. 개발자, 디자이너 등 다양한 직군과 원활하게 소통하며 팀의 목표를 일치시키는 리더십이 요구됩니다. 실패를 두려워하지 않고 빠른 실험과 검증을 통해 배움을 얻는 자세가 PO의 핵심 역량입니다.', 'Career', NOW(), NOW()),
                                                                                ('https://brunch.co.kr/@work/1', '일잘러들의 시간 관리 매트릭스', '쏟아지는 업무 속에서 허우적대지 않고 효율적으로 일하기 위해서는 아이젠하워 매트릭스를 활용한 우선순위 설정이 필수적입니다. 중요하고 긴급한 일, 중요하지만 긴급하지 않은 일 등 4분면으로 업무를 분류하여 처리 순서를 정하세요. 특히 장기적인 성과를 위해서는 중요하지만 긴급하지 않은 일에 시간을 투자하는 것이 핵심입니다. 자투리 시간을 활용하고 불필요한 회의를 줄이는 것도 생산성을 높이는 팁입니다.', 'Career', NOW(), NOW()),
                                                                                ('https://www.linkedin.com/learning/1', '효과적인 커뮤니케이션 스킬 향상', '직장 생활의 8할은 커뮤니케이션이라고 해도 과언이 아닙니다. 자신의 의견을 명확하고 논리적으로 전달하되, 상대방의 말을 경청하고 공감하는 자세가 필요합니다. 텍스트로 소통할 때는 오해의 소지가 없도록 정중하고 명료한 표현을 사용하고, 대면 상황에서는 비언어적인 태도에도 신경 써야 합니다. 피드백을 주고받을 때는 감정이 아닌 사실에 기반하여 건설적인 방향으로 대화하는 것이 좋습니다.', 'Career', NOW(), NOW()),
                                                                                ('https://velog.io/@tech/1', 'MSA 아키텍처의 장단점과 도입 사례', '거대한 모놀리식 애플리케이션을 작은 서비스 단위로 쪼개는 마이크로서비스 아키텍처(MSA)가 현대 소프트웨어 개발의 트렌드로 자리 잡았습니다. 서비스 간 결합도를 낮추어 배포와 확장이 유연하고, 기술 스택을 자유롭게 선택할 수 있다는 장점이 있습니다. 하지만 시스템 복잡도가 증가하고 데이터 일관성 관리가 어려워지는 단점도 존재하므로 도입 시 신중한 검토가 필요합니다. 넷플릭스, 우버 등 글로벌 기업들의 성공 사례를 참고해 보세요.', 'Career', NOW(), NOW()),
                                                                                ('https://www.wanted.co.kr/salary/1', '연봉 협상, 시장 가치 제대로 인정받기', '연봉 협상은 회사가 주는 대로 받는 통보가 아니라 자신의 가치를 증명하고 정당한 대가를 요구하는 비즈니스 과정입니다. 협상 테이블에 앉기 전에 자신의 성과를 객관적인 데이터로 정리하고, 업계 평균 연봉과 시장 상황을 파악해야 합니다. 희망 연봉을 명확하게 제시하되, 회사의 입장도 고려하며 유연하게 조율하는 협상 기술이 필요합니다. 연봉 외에도 인센티브, 스톡옵션, 복지 혜택 등 총 보상 관점에서 접근하는 것이 현명합니다.', 'Career', NOW(), NOW()),
                                                                                ('https://programmers.co.kr/job', '개발자 포트폴리오, 깃허브 관리 꿀팁', '깃허브는 개발자의 실력과 성실함을 보여주는 가장 강력한 포트폴리오입니다. 단순히 코드를 저장하는 것을 넘어, 프로젝트의 개요, 기술 스택, 트러블 슈팅 과정 등을 리드미(README)에 상세히 기록하는 것이 좋습니다. 오픈 소스 프로젝트에 기여하거나 기술 블로그를 운영하는 것도 긍정적인 평가 요소가 됩니다. 꾸준한 커밋 활동은 개발에 대한 열정을 증명하는 지표가 되므로 1일 1커밋에 도전해 보세요.', 'Career', NOW(), NOW()),
                                                                                ('https://www.youtube.com/watch?v=startup1', '스타트업 창업, 아이디어에서 투자 유치까지', '세상을 바꾸는 혁신적인 아이디어가 있다면 스타트업 창업에 도전해 보세요. 하지만 성공적인 창업을 위해서는 아이디어뿐만 아니라 실행력, 팀 빌딩, 자금 조달 등 넘어야 할 산이 많습니다. 초기 단계에서는 가설을 빠르게 검증하고 피봇팅하는 유연함이 필요하며, 데스밸리를 건너기 위한 자금 확보 전략도 중요합니다. 선배 창업가들의 실패와 성공 스토리는 예비 창업가들에게 훌륭한 나침반이 되어줍니다.', 'Career', NOW(), NOW()),
                                                                                ('https://brunch.co.kr/@leadership/1', '좋은 팀장이 되기 위한 피드백의 기술', '팀장은 지시하는 사람이 아니라 팀원들이 최고의 성과를 낼 수 있도록 돕는 서포터이자 코치여야 합니다. 정기적인 1on1 미팅을 통해 팀원의 고충을 듣고 커리어 성장을 위한 조언을 아끼지 마세요. 칭찬은 공개적으로, 질책은 개인적으로 하는 것이 원칙이며, 구체적인 행동에 대해 피드백해야 합니다. 팀원에게 권한을 위임하고 믿고 기다려주는 리더십이 팀 전체의 역량을 키웁니다.', 'Career', NOW(), NOW()),
                                                                                ('https://velog.io/@frontend/1', '리액트 상태 관리 라이브러리 비교', '프론트엔드 개발에서 복잡해지는 상태 관리를 효율적으로 하기 위해 Redux, Recoil, Zustand 등 다양한 라이브러리가 사용되고 있습니다. Redux는 강력한 미들웨어와 개발자 도구를 제공하지만 보일러플레이트 코드가 많다는 단점이 있습니다. 반면 Recoil과 Zustand는 가볍고 직관적인 API를 제공하여 최근 인기를 끌고 있습니다. 프로젝트의 규모와 팀의 선호도에 맞춰 적절한 도구를 선택하는 것이 중요합니다.', 'Career', NOW(), NOW()),
                                                                                ('https://www.linkedin.com/pulse/2', '번아웃 없이 롱런하는 커리어 관리법', '커리어는 단거리가 아니라 마라톤이기에 지치지 않고 꾸준히 나아가는 것이 중요합니다. 일과 삶의 경계를 명확히 하고, 퇴근 후에는 온전한 휴식을 취하며 에너지를 재충전해야 합니다. 끊임없이 새로운 것을 배우며 성장하는 기쁨을 느끼고, 때로는 잠시 멈춰 서서 방향을 점검하는 시간도 필요합니다. 동료들과의 건강한 네트워크는 힘든 시기를 버티게 해주는 든든한 버팀목이 됩니다.', 'Career', NOW(), NOW()),
                                                                                ('https://www.wanted.co.kr/insight/1', '2024년 채용 트렌드와 유망 직무', '디지털 전환이 가속화되면서 AI, 데이터 분석, 사이버 보안 전문가에 대한 수요가 폭발적으로 증가하고 있습니다. 기술 역량뿐만 아니라 소통, 협업, 문제 해결 능력과 같은 소프트 스킬의 중요성도 더욱 커지고 있습니다. 평생직장의 개념이 사라지고 수시 채용이 보편화됨에 따라, 자신의 커리어 포트폴리오를 지속적으로 관리하고 업그레이드해야 합니다. 변화의 흐름을 읽고 준비된 인재에게는 더 많은 기회가 열릴 것입니다.', 'Career', NOW(), NOW());
INSERT INTO links (url, title, ai_summary, content, created_at, updated_at) VALUES
                                                                                ('https://ohou.se/projects/1', '10평대 원룸, 좁은 공간 넓게 쓰는 배치', '한정된 공간을 효율적으로 활용하여 넓어 보이게 만드는 원룸 인테리어 노하우를 공개합니다. 키 낮은 가구를 배치하여 시야를 틔우고, 밝은 화이트나 베이지 톤으로 벽과 가구를 통일하면 공간이 확장된 듯한 착시 효과를 줄 수 있습니다. 공간 분리가 필요하다면 답답한 가벽 대신 책장이나 커튼을 활용하는 것이 좋습니다. 다용도 수납 가구와 틈새 수납 아이템을 적절히 활용하여 죽은 공간을 살리는 것도 꿀팁입니다.', 'Living', NOW(), NOW()),
                                                                                ('https://www.ikea.com/kr/ko/ideas/1', '이케아 템으로 완성하는 미니멀 인테리어', '가성비 좋은 이케아 가구와 소품을 활용해 군더더기 없이 깔끔한 미니멀 라이프를 실현해 보세요. 심플한 디자인의 수납장으로 잡동사니를 숨기고, 포근한 패브릭 소파와 러그로 아늑함을 더하는 것이 포인트입니다. 간접 조명을 활용하면 호텔처럼 고급스러운 분위기를 연출할 수 있습니다. 비움의 미학을 실천하며 내가 좋아하는 물건들로만 채운 공간은 온전한 휴식을 선물합니다.', 'Living', NOW(), NOW()),
                                                                                ('https://www.pinterest.co.kr/ideas/1', '식물 초보를 위한 플랜테리어 가이드', '집 안에 초록 식물을 들이면 공기 정화는 물론 심리적인 안정감까지 얻을 수 있는 플랜테리어가 완성됩니다. 식물 키우기에 자신이 없다면 생명력이 강하고 관리가 쉬운 몬스테라, 스킨답서스, 산세베리아부터 시작해 보세요. 토분이나 라탄 바구니 등 화분 커버를 활용하면 인테리어 효과를 배가시킬 수 있습니다. 햇빛과 물, 통풍의 3박자만 잘 맞춰주면 반려 식물과 함께하는 싱그러운 일상을 즐길 수 있습니다.', 'Living', NOW(), NOW()),
                                                                                ('https://blog.naver.com/living/1', '호텔 같은 욕실 만드는 건식 화장실 팁', '물기 없이 보송보송한 건식 욕실은 곰팡이 걱정을 덜어주고 쾌적한 사용감을 제공합니다. 샤워 부스나 파티션을 설치하여 물이 튀는 것을 막고, 바닥에는 러그나 조립식 데크를 깔아주면 맨발로도 드나들 수 있습니다. 세면대 위에는 디퓨저와 핸드워시를 예쁘게 진열하고, 수건은 호텔식으로 접어 보관해 보세요. 작은 변화만으로도 매일 사용하는 욕실이 힐링 공간으로 탈바꿈합니다.', 'Living', NOW(), NOW()),
                                                                                ('https://ohou.se/advices/1', '전세집 인테리어, 못 없이 액자 거는 법', '내 집이 아니라서 벽에 못을 박기 꺼려진다면, 벽지 손상 없이 액자나 소품을 걸 수 있는 다양한 방법들을 활용해 보세요. 핀 자국이 거의 남지 않는 꼭꼬핀이나 강력한 접착력의 블루택, 실리콘 테이프 등이 유용합니다. 레일 액자 걸이를 설치하면 못 자국 없이 갤러리처럼 멋스러운 연출이 가능합니다. 벽에 기대어 놓거나 선반 위에 올려두는 것만으로도 감각적인 스타일링이 완성됩니다.', 'Living', NOW(), NOW()),
                                                                                ('https://www.ikea.com/kr/ko/rooms/kitchen/1', '요리가 즐거워지는 주방 수납 정리법', '복잡하고 어수선한 주방을 깔끔하게 정리하면 요리 시간이 단축되고 즐거워집니다. 자주 사용하는 조리 도구는 손이 닿기 쉬운 곳에 걸어두고, 양념통은 통일된 용기에 담아 라벨링을 하면 찾기 쉽고 보기에도 좋습니다. 싱크대 하부장에는 프라이팬 정리대나 파일 박스를 활용해 냄비와 팬을 세워서 보관하면 공간 효율이 높아집니다. 서랍 속은 칸막이를 이용해 커트러리와 자잘한 도구들을 분류해 보세요.', 'Living', NOW(), NOW()),
                                                                                ('https://www.pinterest.co.kr/diy/1', '오래된 가구 리폼, 페인트 칠하기 DIY', '유행이 지났거나 낡은 가구를 버리지 않고 페인트 리폼을 통해 새것처럼 변신시켜 보세요. 사포질로 표면을 매끄럽게 다듬고 젯소를 발라 밑바탕을 만든 뒤, 원하는 컬러의 페인트를 얇게 여러 번 칠해주면 됩니다. 손잡이만 교체해도 가구의 분위기가 확 달라집니다. 내 손으로 직접 고치고 꾸민 가구는 세상에 하나뿐인 나만의 작품이 되어 공간에 특별함을 더해줍니다.', 'Living', NOW(), NOW()),
                                                                                ('https://blog.naver.com/interior/1', '조명의 마법, 간접등으로 분위기 바꾸기', '인테리어의 완성은 조명이라는 말이 있듯이, 빛의 색과 위치만 바꿔도 집안 분위기가 드라마틱하게 변합니다. 천장 형광등 대신 플로어 스탠드나 단스탠드를 활용해 은은한 간접 조명을 연출해 보세요. 따뜻한 색감의 전구색 조명은 아늑하고 편안한 느낌을, 하얀 주백색 조명은 깨끗하고 모던한 느낌을 줍니다. 침대 헤드나 커튼 박스에 라인 조명을 설치하면 세련된 무드를 더할 수 있습니다.', 'Living', NOW(), NOW()),
                                                                                ('https://ohou.se/projects/2', '재택근무를 위한 홈오피스 서재 꾸미기', '집에서도 업무 효율을 높일 수 있는 나만의 홈오피스 공간을 꾸며보세요. 집중력을 높여주는 차분한 컬러의 벽지와 눈이 편안한 조명을 선택하는 것이 좋습니다. 책상은 창문을 등지거나 측면에 배치하여 모니터 반사를 줄이고, 장시간 앉아 있어도 허리가 편안한 인체공학적 의자를 투자하세요. 좋아하는 책과 소품으로 영감을 주는 공간을 만들면 일의 능률도 오르고 창의력도 샘솟습니다.', 'Living', NOW(), NOW()),
                                                                                ('https://www.ikea.com/kr/ko/ideas/sustainable/1', '지속 가능한 삶, 제로웨이스트 살림법', '지구를 생각하는 제로웨이스트 라이프는 거창한 것이 아니라 일상 속 작은 실천에서 시작됩니다. 플라스틱 용기 대신 유리병이나 스테인리스 용기를 사용하고, 비닐봉지 대신 장바구니와 프로듀스 백을 챙기는 습관을 들여보세요. 천연 수세미와 소프넛 세제 등 친환경 살림 아이템을 활용하는 것도 좋은 방법입니다. 쓰레기를 줄이고 환경을 보호하는 착한 살림은 나와 가족의 건강을 지키는 길이기도 합니다.', 'Living', NOW(), NOW()),
                                                                                ('https://www.pinterest.co.kr/color/1', '2024 인테리어 컬러 트렌드, 피치 퍼즈', '팬톤이 선정한 올해의 컬러 피치 퍼즈는 부드럽고 따뜻한 복숭아색으로, 공간에 평온함과 치유의 메시지를 전달합니다. 벽지나 커튼처럼 넓은 면적에 사용하면 포근하고 사랑스러운 분위기를 연출할 수 있습니다. 부담스럽다면 쿠션, 화병, 포스터 등 작은 소품으로 포인트를 주는 것도 좋습니다. 화이트, 베이지, 그레이 등 뉴트럴 컬러와 매치하면 세련되면서도 감각적인 인테리어가 완성됩니다.', 'Living', NOW(), NOW()),
                                                                                ('https://blog.naver.com/clean/1', '장마철 빨래 냄새 잡는 세탁 노하우', '습도 높은 장마철, 빨래에서 나는 퀴퀴한 냄새 때문에 고민이라면 세탁법을 바꿔보세요. 헹굼 단계에서 식초를 한 스푼 넣으면 살균 효과와 함께 냄새를 제거할 수 있습니다. 세탁조 청소를 주기적으로 하여 곰팡이를 제거하고, 세탁 후에는 문을 열어 내부를 건조시켜야 합니다. 실내 건조 시에는 선풍기나 제습기를 틀어 건조 시간을 단축시키는 것이 냄새 예방의 지름길입니다.', 'Living', NOW(), NOW()),
                                                                                ('https://ohou.se/advices/2', '좁은 베란다, 나만의 홈카페로 변신', '창고로 방치되기 쉬운 베란다를 정리하여 햇살 가득한 홈카페로 꾸며보세요. 바닥에 조립식 데크 타일이나 인조 잔디를 깔면 맨발로 드나들 수 있는 아늑한 공간이 됩니다. 접이식 테이블과 의자를 배치하고, 감성적인 조명과 식물을 더하면 분위기 좋은 카페가 부럽지 않습니다. 커피 한 잔과 책 한 권의 여유를 즐기며 바쁜 일상 속 쉼표를 찍어보세요.', 'Living', NOW(), NOW()),
                                                                                ('https://www.ikea.com/kr/ko/rooms/kids/1', '아이 방 정리 정돈, 스스로 하게 만드는 법', '아이 방 정리는 엄마의 숙제가 아니라 아이의 자립심을 키워주는 교육의 기회입니다. 아이의 눈높이에 맞는 낮은 수납장을 배치하고, 장난감 종류별로 바구니에 담아 그림 라벨을 붙여주면 아이 스스로 정리하기 쉽습니다. 놀이가 끝난 후 정리하는 시간을 정해두고, 잘했을 때는 아낌없이 칭찬해 주세요. 정리 정돈 습관은 물건을 소중히 여기는 마음과 책임감을 길러줍니다.', 'Living', NOW(), NOW()),
                                                                                ('https://www.pinterest.co.kr/storage/1', '드레스룸 정리의 정석, 옷 개는 법', '옷장 정리가 어렵다면 옷 개는 법부터 바꿔보세요. 티셔츠, 바지, 속옷 등 종류별로 각을 맞춰 접어 세로로 수납하면 한눈에 보기도 쉽고 꺼내 입기도 편리합니다. 계절이 지난 옷은 리빙 박스에 넣어 상단 선반이나 침대 밑에 보관하고, 자주 입는 옷은 행거에 걸어두세요. 옷걸이를 통일하면 훨씬 깔끔해 보이며, 입지 않는 옷은 과감하게 비우는 것이 정리의 시작입니다.', 'Living', NOW(), NOW());
INSERT INTO user_links (user_id, link_id, status, view_count, why, memo, created_at, updated_at)
INSERT INTO reference_user_links (reference_id, user_link_id, created_at, updated_at)
